10	- Produces (config):
11	  ```ts
12	  export type VehicleTypeId = 'car' | 'bus' | 'bike';
13	  CONFIG.vehicles = {
14	    types: { car: { len: 4.5, w: 1.95, h: 1.2 }, bike: { len: 1.8, w: 0.7, h: 1.6 }, bus: { len: 7.0, w: 2.1, h: 2.7 } },   // m
15	    carColors: number[],     // ≥ 8 màu rực: cam, vàng, đỏ, trắng, xanh dương, xanh lá, xám đậm, đen …
16	    bikeColors: number[],    // giữ 5 màu BIKE_COLORS hiện có trong src/common/traffic.ts
17	    shirtColors: number[],   // ≥ 6 màu áo người lái
18	    palette: { glass, tyre, dark, seat, skin, trouser, busBody, busStripe, busStripeEdge, busWindow, busAc, headDay, tailDay },   // màu cố định theo đỉnh
19	    lamp: { head: [2.2, 2.1, 1.8], tail: [2.0, 0.1, 0.05], nightOn: 0.3 },   // giữ đúng giá trị MAT.headLamp / MAT.tailLamp và ngưỡng 0,3 hiện tại
20	    roughness: number, metalness: number,
21	    maxVerts: 2000
22	  }
