+  k.loft([{ x: -2.0, w: 0.6, y0: 0.8, ym: 0.86, y1: 0.9, t: 0.7 }, { x: -0.78, w: 0.73, y0: 0.78, ym: 1.02, y1: 1.14, t: 0.66 }], null, Role.Paint);   // nắp máy sau
+  k.box(0.95, 0.05, 0.98, -0.32, 1.145, 0, null, Role.Paint);                                                   // mái
